import {workspaceReport} from './app.mjs?v=1.1.0';
import {pageShell,esc,fmt,source,downloadFile} from './ocean-ui.mjs';
const TITLES=['工况与模型','分析窗口','响应结果','对比与结论','数据来源'];
export function initializeReports(){
 const {root}=pageShell('reports','分析报告','07 / EVIDENCE REPORT STUDIO','把计算过程与结论，整理成可追溯的报告。','<button type="button" class="ow-primary" id="op-pdf" title="打开打印窗口，选择另存为 PDF">▤ 导出 PDF</button><button type="button" class="ow-button" id="op-markdown">⇩ 导出 Markdown</button><button type="button" class="ow-button" id="op-save">▣ 保存报告</button>');
 root.insertAdjacentHTML('beforeend',`<div class="op-grid"><aside class="ow-glass op-outline"><h2>报告目录</h2><nav aria-label="报告章节">${TITLES.map((title,i)=>`<button type="button" data-report-page="${i}"><span>0${i+1}</span>${title}</button>`).join('')}</nav><button type="button" class="ow-quiet" id="op-original">完整报告预览 ↗</button><button type="button" class="ow-quiet" id="op-saved">恢复上次保存</button><p class="op-save-status" role="status"></p></aside><section class="op-reader ow-glass"><div class="op-paper" tabindex="0" aria-label="报告正文"></div><footer><button type="button" id="op-prev" aria-label="报告上一页">‹</button><span id="op-pagination"></span><button type="button" id="op-next" aria-label="报告下一页">›</button></footer></section><aside class="ow-glass op-evidence"><header><h2>结论与依据</h2><button type="button" class="ow-button" id="op-ai">✧ AI 辅助撰写</button></header><div class="op-evidence-cards"></div><p class="op-ai-answer" role="status" hidden></p><div class="op-note"><strong>ⓘ 报告说明</strong><p>报告使用原始记录的分析窗口。结果分析页的显示范围与转速插值用于交互查看，不会覆盖原始计算参数或真实统计。</p></div></aside></div>`);
 let state=null,index=0,pages=[],fullHTML='',signature='',markdown='',requestId=null,savedView=false;
 const paper=root.querySelector('.op-paper'),saveStatus=root.querySelector('.op-save-status'),answer=root.querySelector('.op-ai-answer');
 function safeSavedHTML(html){
  if(typeof html!=='string'||html.length>2000000)throw Error('invalid saved report');
  const template=document.createElement('template');template.innerHTML=html;
  const allowed=new Set('article div span p h1 h2 h3 h4 table thead tbody tr th td a ul ol li br b strong em small code svg defs clippath path g line rect circle text title'.split(' '));
  template.content.querySelectorAll('*').forEach(node=>{if(!allowed.has(node.tagName.toLowerCase())){node.remove();return;}for(const attr of [...node.attributes]){if(/^on/i.test(attr.name)||['src','srcdoc','style'].includes(attr.name)||(/href$/i.test(attr.name)&&!(/^(https?:|#|\.\/)/i.test(attr.value))))node.removeAttribute(attr.name);}});
  return template.innerHTML;
 }
 function paginate(html){const holder=document.createElement('div');holder.innerHTML=html;const article=holder.querySelector('.report-body');if(!article)return ['<p>暂无可用报告。</p>'];const sections=[],intro=[];let current=null;for(const node of article.children){if(node.tagName==='H2'){current=[];sections.push(current);}if(current)current.push(node.outerHTML);else intro.push(node.outerHTML);}const grouped=[[...intro,...(sections[0]||[])],sections[1]||[],[...(sections[2]||[]),...(sections[3]||[])],[...(sections[4]||[]),...(sections[5]||[]),...(sections[6]||[])],sections[7]||[]];return grouped.map((nodes,i)=>`<article class="report-body">${i?'<div class="op-document-label">TIDEFLOW / '+TITLES[i]+'</div>':''}${nodes.join('')}</article>`);}
 function toMarkdown(html){const holder=document.createElement('div');holder.innerHTML=html;let result='';const article=holder.querySelector('.report-body');if(!article)return '';for(const node of article.children){if(/^H[1-6]$/.test(node.tagName))result+='\n'+'#'.repeat(Number(node.tagName[1]))+' '+node.textContent.trim()+'\n\n';else if(node.tagName==='TABLE'){const rows=[...node.rows].map(row=>[...row.cells].map(cell=>cell.textContent.trim().replace(/\|/g,'\\|').replace(/\n/g,' ')));result+=rows.map((row,i)=>'| '+row.join(' | ')+' |'+(i===0?'\n| '+row.map(()=>'---').join(' | ')+' |':'')).join('\n')+'\n\n';}else if(node.querySelector('svg'))result+='[时序图请查看网页报告或 PDF；原始数值可从结果分析导出。]\n\n';else if(node.tagName==='UL')result+=[...node.children].map(li=>'- '+li.textContent.trim()).join('\n')+'\n\n';else result+=node.textContent.trim()+'\n\n';}result+='\n## 参考链接\n\n';holder.querySelectorAll('a[href]').forEach(a=>result+=`- [${a.textContent.trim()}](${a.getAttribute('href')})\n`);return result;}
 function show(){paper.innerHTML=pages[index]||'<div class="ow-empty">选择已完成的工况后，报告将在这里生成。</div>';paper.scrollTop=0;root.querySelector('#op-pagination').textContent=pages.length?`${index+1} / ${pages.length}`:'0 / 0';root.querySelector('#op-prev').disabled=!pages.length||index===0;root.querySelector('#op-next').disabled=!pages.length||index===pages.length-1;root.querySelectorAll('[data-report-page]').forEach(button=>{const active=Number(button.dataset.reportPage)===index;button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});}
 root.querySelectorAll('[data-report-page]').forEach(button=>button.onclick=()=>{index=Number(button.dataset.reportPage);show();});root.querySelector('#op-prev').onclick=()=>{index=Math.max(0,index-1);show();};root.querySelector('#op-next').onclick=()=>{index=Math.min(pages.length-1,index+1);show();};
 root.querySelector('#op-original').onclick=()=>{if(!fullHTML)return;document.getElementById('report-preview').innerHTML=fullHTML;document.getElementById('report-dialog').showModal();};root.querySelector('#op-pdf').onclick=()=>{if(!fullHTML)return;document.getElementById('print-area').innerHTML=fullHTML;window.print();};root.querySelector('#op-markdown').onclick=()=>{if(markdown)downloadFile('潮汐-海上风电分析报告.md',markdown,'text/markdown;charset=utf-8');};
 root.querySelector('#op-save').onclick=()=>{if(!fullHTML)return;try{localStorage.setItem('tideflow-report-saved-v1',JSON.stringify({html:fullHTML,recordId:state.record?.id,saved:new Date().toISOString()}));saveStatus.textContent='已保存至此浏览器 · '+new Date().toLocaleTimeString('zh-CN');}catch{saveStatus.textContent='保存失败：浏览器存储不可用，请导出 Markdown 或 PDF。';}};
 root.querySelector('#op-saved').onclick=()=>{try{const saved=JSON.parse(localStorage.getItem('tideflow-report-saved-v1')||'null');if(!saved?.html){saveStatus.textContent='尚未保存报告。';return;}if(!saved.html.startsWith('<article class="report-body">'))throw Error('invalid saved report');fullHTML=safeSavedHTML(saved.html);pages=paginate(fullHTML);markdown=toMarkdown(fullHTML);savedView=true;index=0;show();root.querySelectorAll('#op-pdf,#op-markdown,#op-save,#op-original').forEach(button=>button.disabled=false);root.querySelector('.op-evidence-cards').innerHTML='<p class="op-note">正在查看已保存的报告快照，其工况和时间以正文为准。</p>';saveStatus.textContent='已恢复 '+new Date(saved.saved).toLocaleString('zh-CN')+' 的报告快照。';}catch{saveStatus.textContent='保存的报告无法读取，请重新生成。';}};
 root.querySelector('#op-ai').onclick=()=>{const record=state?.record;if(!record?.result)return;requestId=crypto.randomUUID();answer.hidden=false;answer.textContent='正在结合当前工况与结果整理报告说明…';window.dispatchEvent(new CustomEvent('tideflow:engineering-ask',{detail:{requestId,question:'请为当前真实工况撰写一段可核查的报告摘要。仅使用所给统计，注明分析窗口与来源，不外推年发电量，不判断工程安全。',module:{name:'分析报告',title:record.name,description:JSON.stringify({params:record.params,stats:record.result.stats,window:[record.result.analysis_start,record.result.analysis_end]}),fields:JSON.stringify({source:source(record),output_sha256:record.result.output_sha256,findings:record.findings})}}}));};
 window.addEventListener('tideflow:engineering-answer',e=>{if(e.detail.requestId===requestId){answer.hidden=false;answer.textContent=e.detail.text;}});
 root.querySelector('.op-evidence-cards').onclick=e=>{const button=e.target.closest('[data-evidence-page]');if(button){index=Number(button.dataset.evidencePage);show();}};
 function update(next){state=next;const r=next.record,key=(r?.id||'')+'|'+r?.status+'|'+next.comparison.join(',');if(key===signature)return;signature=key;savedView=false;requestId=null;answer.hidden=true;saveStatus.textContent='';const ready=!!r?.result;root.querySelectorAll('#op-pdf,#op-markdown,#op-save,#op-original,#op-ai').forEach(button=>button.disabled=!ready);if(!ready){pages=[];fullHTML='';markdown='';root.querySelector('.op-evidence-cards').innerHTML='<p class="ow-empty">选择已完成的有效工况以生成报告。</p>';show();return;}try{fullHTML=workspaceReport();pages=paginate(fullHTML);markdown=toMarkdown(fullHTML);}catch(error){pages=[];saveStatus.textContent=error.message;}index=Math.min(index,Math.max(0,pages.length-1));show();const result=r.result;const cards=[['窗口内功率统计',`在 ${result.analysis_start}—${result.analysis_end} s 原始分析窗口，平均功率 ${fmt(result.stats.GenPwr.mean,1)} kW，窗口电量 ${fmt(result.energy_kwh,3)} kWh。短时统计不外推年发电量。`,'原始输出 · 发电功率时序',2],['平台运动响应',`纵摇绝对峰值 ${fmt(result.stats.PtfmPitch.max_abs,3)}°，纵荡绝对峰值 ${fmt(result.stats.PtfmSurge.max_abs,3)} m。当前通道不用于直接判断系泊安全。`,'响应时序 · 窗口复核',3],['计算证据与来源',`${source(r)} · ${result.full_samples} 个样本；${r.findings?.length?'日志匹配 '+r.findings.length+' 条提示，请结合原文复核。':'日志规则未匹配常见异常，仍需核查模型适用性。'}`,'输入哈希 · 日志与数据来源',4]];root.querySelector('.op-evidence-cards').innerHTML=cards.map(([title,text,label,target],i)=>`<article><span class="op-evidence-index">0${i+1}</span><div><h3>${title}</h3><p>${esc(text)}</p><button type="button" data-evidence-page="${target}">▤ ${label} <b>›</b></button></div></article>`).join('');}
 return {update};
}
